 void startSystemSyncInBackground(){if(syncStarted||systemSynced||!getPackageName().equals(Telephony.Sms.getDefaultSmsPackage(this)))return;syncStarted=true;new Thread(()->{boolean ok=syncSystemMessages();if(isFinishing()||isDestroyed())return;runOnUiThread(()->{if(ok){systemSynced=true;if(list!=null)render();}else syncStarted=false;});},"hashem-sms-sync").start();}
 boolean syncSystemMessages(){
  if(!getPackageName().equals(Telephony.Sms.getDefaultSmsPackage(this)))return false;
  android.database.Cursor c=null;boolean ok=false;
  android.content.SharedPreferences prefs=getSharedPreferences("sms_sync",MODE_PRIVATE);
  long lastSync=prefs.getLong("last_successful_sync",0L);
  String selection=lastSync>0?Telephony.Sms.DATE+">=?":null;
  String[] args=lastSync>0?new String[]{String.valueOf(Math.max(0,lastSync-120000L))}:null;
  try{
   c=getContentResolver().query(Telephony.Sms.CONTENT_URI,new String[]{Telephony.Sms._ID,Telephony.Sms.ADDRESS,Telephony.Sms.BODY,Telephony.Sms.TYPE,Telephony.Sms.DATE,Telephony.Sms.READ},selection,args,Telephony.Sms.DATE+" DESC");
   if(c!=null){
    ArrayList<Object[]> batch=new ArrayList<>(500);
    while(c.moveToNext()){
     batch.add(new Object[]{c.getLong(0),c.getString(1),c.getString(2),c.getInt(3),c.getLong(4),c.getInt(5)});
     if(batch.size()==500){if(!db.importSystemMessageBatch(batch))return false;batch.clear();}
    }
    if(!batch.isEmpty()&&!db.importSystemMessageBatch(batch))return false;
    ok=true;
   }else android.util.Log.e("HashemSMS","Android SMS provider query returned null during sync");
  }catch(Exception e){android.util.Log.e("HashemSMS","System SMS synchronization failed",e);ok=false;}
  finally{try{if(c!=null)c.close();}catch(Exception e){android.util.Log.e("HashemSMS","Failed to close Android SMS provider cursor",e);}}
  if(ok)prefs.edit().putLong("last_successful_sync",System.currentTimeMillis()).apply();
  return ok;
 }
