 void showContactsScreen(){
  threadHandler.removeCallbacks(threadRefreshRunnable);threadHandler.removeCallbacks(searchFilterRunnable);threadsRecycler.setVisibility(View.GONE);emptyThreadsView.setVisibility(View.GONE);otherScroll.setVisibility(View.GONE);contactsScreen.setVisibility(View.VISIBLE);updateBottomNavigation();
  if(checkSelfPermission("android.permission.READ_CONTACTS")!=PackageManager.PERMISSION_GRANTED){contactsRecycler.setVisibility(View.GONE);showContactsPermissionState();promptContactsPermissionExplanationOnce();return;}
  contactsState.setVisibility(View.GONE);contactsRecycler.setVisibility(View.VISIBLE);if(!contactsLoaded)loadContactsAsync();else filterContacts(search==null?"":search.getText().toString());
 }
 void showContactsPermissionState(){contactsState.setVisibility(View.VISIBLE);contactsRecycler.setVisibility(View.GONE);contactsStateText.setText("يلزم إذن جهات الاتصال لعرض الأسماء والأرقام. يمكنك منح الإذن أو فتح إعدادات التطبيق؛ لن نغيّر جهات الاتصال أو الرسائل.");boolean asked=getSharedPreferences("runtime_permissions",MODE_PRIVATE).getBoolean("contacts_permission_requested",false);boolean canAsk=!asked||shouldShowRequestPermissionRationale("android.permission.READ_CONTACTS");contactsPermissionButton.setVisibility(View.VISIBLE);contactsPermissionButton.setText(canAsk?"منح الإذن":"فتح الإعدادات");}
 void promptContactsPermissionExplanationOnce(){android.content.SharedPreferences prefs=getSharedPreferences("runtime_permissions",MODE_PRIVATE);if(prefs.getBoolean("contacts_permission_explained",false))return;prefs.edit().putBoolean("contacts_permission_explained",true).apply();new AlertDialog.Builder(this).setTitle("السماح بجهات الاتصال").setMessage("يحتاج هذا التبويب إلى إذن قراءة جهات الاتصال لعرض الأسماء والأرقام وربطها بالمحادثات الموجودة. لا يغيّر هذا الإذن جهات الاتصال ولا عناوين الرسائل المخزنة.").setNegativeButton("ليس الآن",null).setPositiveButton("متابعة",(d,w)->requestContactsPermission()).show();}
 void onContactsPermissionAction(){if(checkSelfPermission("android.permission.READ_CONTACTS")==PackageManager.PERMISSION_GRANTED){showContactsScreen();return;}android.content.SharedPreferences prefs=getSharedPreferences("runtime_permissions",MODE_PRIVATE);boolean asked=prefs.getBoolean("contacts_permission_requested",false);if(asked&&!shouldShowRequestPermissionRationale("android.permission.READ_CONTACTS")){new AlertDialog.Builder(this).setTitle("إعدادات إذن جهات الاتصال").setMessage("يبدو أن طلب الإذن لم يعد يظهر. افتح إعدادات التطبيق وفعّل إذن جهات الاتصال يدويًا.").setNegativeButton("إلغاء",null).setPositiveButton("فتح الإعدادات",(d,w)->{Intent i=new Intent(android.provider.Settings.ACTION_APPLICATION_DETAILS_SETTINGS,Uri.parse("package:"+getPackageName()));startActivity(i);}).show();return;}new AlertDialog.Builder(this).setTitle("إذن جهات الاتصال").setMessage("يُستخدم الإذن لقراءة الأسماء والأرقام فقط حتى تظهر القائمة وتُفتح المحادثة الصحيحة.").setNegativeButton("ليس الآن",null).setPositiveButton("منح الإذن",(d,w)->requestContactsPermission()).show();}
 void requestContactsPermission(){getSharedPreferences("runtime_permissions",MODE_PRIVATE).edit().putBoolean("contacts_permission_requested",true).apply();requestPermissions(new String[]{"android.permission.READ_CONTACTS"},81);}

