 /**
  * Applies shared spacing and input sizing only to secondary management screens.
  * The conversations home, contacts tab, and More landing page are intentionally untouched.
  */
 void styleSecondaryScreen(){
  if(list==null)return;
  for(int i=0;i<list.getChildCount();i++){
   View child=list.getChildAt(i);
   if(child instanceof EditText){
    EditText field=(EditText)child;
    field.setTextColor(UiResources.color(this,R.color.on_surface));
    field.setHintTextColor(UiResources.color(this,R.color.on_surface_variant));
    field.setPadding(UiResources.dp(this,14),UiResources.dp(this,10),UiResources.dp(this,14),UiResources.dp(this,10));
    field.setBackground(rounded(UiResources.color(this,R.color.surface_variant),UiResources.color(this,R.color.search_border),14));
    field.setMinHeight(UiResources.dp(this,48));
   }else if(child instanceof Button){
    Button action=(Button)child;
    action.setAllCaps(false);
    action.setMinHeight(UiResources.dp(this,44));
    action.setPadding(UiResources.dp(this,14),UiResources.dp(this,8),UiResources.dp(this,14),UiResources.dp(this,8));
    action.setStateListAnimator(null);
   }else if(child instanceof LinearLayout && child.getBackground()==null){
    LinearLayout card=(LinearLayout)child;
    int pad=UiResources.dp(this,12);
    card.setPadding(pad,pad,pad,pad);
    card.setBackground(rounded(UiResources.color(this,R.color.card_surface),UiResources.color(this,R.color.card_stroke),UiResources.dp(this,16)));
   }
   ViewGroup.LayoutParams raw=child.getLayoutParams();
   if(raw instanceof LinearLayout.LayoutParams){
    LinearLayout.LayoutParams lp=(LinearLayout.LayoutParams)raw;
    if(lp.bottomMargin<UiResources.dp(this,6))lp.bottomMargin=UiResources.dp(this,6);
    child.setLayoutParams(lp);
   }
  }
 }

 void starredScreen(){list.addView(tv("الرسائل المميزة",22));list.addView(tv("تظهر هنا الرسائل التي وضعت عليها نجمة داخل المحادثات.",14));android.database.Cursor c=db.list("starred");int n=0;String q=search.getText().toString().trim().toLowerCase(Locale.ROOT);while(c.moveToNext()){String a=c.getString(c.getColumnIndexOrThrow("address")),body=c.getString(c.getColumnIndexOrThrow("body")),status=c.getString(c.getColumnIndexOrThrow("status"));if(!q.isEmpty()&&!a.toLowerCase(Locale.ROOT).contains(q)&&!body.toLowerCase(Locale.ROOT).contains(q))continue;LinearLayout row=new LinearLayout(this);row.setOrientation(LinearLayout.VERTICAL);TextView starredTitle=tv(contactName(a)+"  ·  "+a,16);starredTitle.setCompoundDrawablesRelativeWithIntrinsicBounds(R.drawable.ic_star,0,0,0);starredTitle.setCompoundDrawablePadding(UiResources.dp(MainActivity.this,6));row.addView(starredTitle);row.addView(tv(body,16));row.addView(tv(status,12));row.setOnClickListener(v->{Intent i=new Intent(this,ConversationActivity.class);i.putExtra("address",a);startActivity(i);});list.addView(row);View line=new View(this);line.setBackgroundColor(UiResources.color(MainActivity.this,R.color.divider));list.addView(line,new LinearLayout.LayoutParams(-1,1));n++;}c.close();if(n==0)list.addView(tv("لا توجد رسائل مميزة حاليًا",17));}
 void trashScreen(){list.addView(tv("المهملات",22));list.addView(tv("استعد الرسائل المحذوفة أو احذفها نهائيًا.",14));android.database.Cursor c=db.listTrash();int n=0;while(c.moveToNext()){long id=c.getLong(c.getColumnIndexOrThrow("id"));String a=c.getString(c.getColumnIndexOrThrow("address")),body=c.getString(c.getColumnIndexOrThrow("body")),status=c.getString(c.getColumnIndexOrThrow("status"));if(!search.getText().toString().trim().isEmpty()&&!a.contains(search.getText().toString().trim())&&!body.contains(search.getText().toString().trim()))continue;LinearLayout card=new LinearLayout(this);card.setOrientation(LinearLayout.VERTICAL);styleScreenCard(card);card.addView(tv("من/إلى: "+a,16));card.addView(tv(body,16));card.addView(tv("الحالة السابقة: "+status,13));LinearLayout actions=new LinearLayout(this);Button restore=button("استعادة");restore.setOnClickListener(v->new AlertDialog.Builder(this).setTitle("استعادة الرسالة").setMessage("ستعود الرسالة إلى المحادثة الأصلية.").setNegativeButton("إلغاء",null).setPositiveButton("استعادة",(d,w)->{db.restoreTrashMessage(id);render();}).show());Button remove=button("حذف نهائي");remove.setOnClickListener(v->new AlertDialog.Builder(this).setTitle("حذف نهائي").setMessage("لا يمكن التراجع عن حذف هذه الرسالة نهائيًا.").setNegativeButton("إلغاء",null).setPositiveButton("حذف نهائي",(d,w)->{db.permanentlyDeleteTrashMessage(id);render();}).show());actions.addView(restore,new LinearLayout.LayoutParams(0,-2,1));actions.addView(remove,new LinearLayout.LayoutParams(0,-2,1));card.addView(actions);list.addView(card);View line=new View(this);line.setBackgroundColor(UiResources.color(MainActivity.this,R.color.divider));list.addView(line,new LinearLayout.LayoutParams(-1,1));n++;}c.close();if(n==0)list.addView(tv("المهملات فارغة",17));}
 void failedScreen(){list.addView(tv("الرسائل التي تعذّر إرسالها",22));list.addView(tv("يمكنك مراجعة الرسالة ومحاولة إرسالها مرة أخرى.",14));android.database.Cursor c=db.list("failed");int n=0;while(c.moveToNext()){String a=c.getString(c.getColumnIndexOrThrow("address")),body=c.getString(c.getColumnIndexOrThrow("body")),st=c.getString(c.getColumnIndexOrThrow("status"));if(!search.getText().toString().trim().isEmpty()&&!a.contains(search.getText().toString().trim())&&!body.contains(search.getText().toString().trim()))continue;LinearLayout card=new LinearLayout(this);card.setOrientation(LinearLayout.VERTICAL);styleScreenCard(card);card.addView(tv("إلى: "+a,17));card.addView(tv(body,16));card.addView(tv("الحالة: "+st,13));Button retry=button("إعادة الإرسال إلى الرقم الأصلي");retry.setOnClickListener(v->new AlertDialog.Builder(this).setTitle("إعادة إرسال الرسالة؟").setMessage("سيتم إرسال الرسالة مرة أخرى إلى "+a).setNegativeButton("إلغاء",null).setPositiveButton("إرسال", (d,w)->send(a,body)).show());card.addView(retry);Button forward=button("توجيه عبر قاعدة مسماة");forward.setOnClickListener(v->forwardFailedWithRule(a,body));card.addView(forward);list.addView(card);View line=new View(this);line.setBackgroundColor(UiResources.color(MainActivity.this,R.color.divider));list.addView(line,new LinearLayout.LayoutParams(-1,1));n++;}c.close();if(n==0)list.addView(tv("لا توجد رسائل فاشلة حاليًا",17));}
 void forwardRulesScreen(){list.addView(tv("قواعد توجيه الرسائل الفاشلة",22));list.addView(tv("أنشئ قاعدة باسم واضح ورقم بديل. لا يتم توجيه أي رسالة تلقائيًا؛ اختر القاعدة يدويًا لكل رسالة فاشلة لتجنب إرسال محتوى دون قصد.",14));Button add=button("إضافة قاعدة توجيه");add.setCompoundDrawablesRelativeWithIntrinsicBounds(R.drawable.ic_add,0,0,0);add.setCompoundDrawablePadding(UiResources.dp(MainActivity.this,6));add.setOnClickListener(v->createForwardRuleDialog());list.addView(add);android.database.Cursor c=db.listForwardRules();int n=0;while(c.moveToNext()){long id=c.getLong(c.getColumnIndexOrThrow("id"));String name=c.getString(c.getColumnIndexOrThrow("name"));String number=c.getString(c.getColumnIndexOrThrow("destination"));LinearLayout card=new LinearLayout(this);card.setOrientation(LinearLayout.VERTICAL);styleScreenCard(card);card.addView(tv(name,18));card.addView(tv("رقم التوجيه: "+number,15));Button del=button("حذف القاعدة");del.setOnClickListener(v->new AlertDialog.Builder(this).setTitle("حذف قاعدة التوجيه").setMessage("هل تريد حذف قاعدة \""+name+"\"؟").setNegativeButton("إلغاء",null).setPositiveButton("حذف",(d,w)->{db.deleteForwardRule(id);render();}).show());card.addView(del);list.addView(card);View line=new View(this);line.setBackgroundColor(UiResources.color(MainActivity.this,R.color.divider));list.addView(line,new LinearLayout.LayoutParams(-1,1));n++;}c.close();if(n==0)list.addView(tv("لا توجد قواعد توجيه. أضف قاعدة لتظهر هنا.",16));}
 void createForwardRuleDialog(){LinearLayout p=new LinearLayout(this);p.setOrientation(LinearLayout.VERTICAL);EditText name=new EditText(this);name.setHint("اسم القاعدة، مثل رقم بديل للعمل");EditText number=new EditText(this);number.setHint("رقم الهاتف الذي ستُوجّه إليه الرسالة");number.setInputType(3);p.addView(name);p.addView(number);new AlertDialog.Builder(this).setTitle("إضافة قاعدة توجيه").setView(p).setNegativeButton("إلغاء",null).setPositiveButton("حفظ",(d,w)->{String n=name.getText().toString().trim(),a=number.getText().toString().trim();if(n.isEmpty()||a.isEmpty()){Toast.makeText(this,"أدخل اسم القاعدة ورقم التوجيه",Toast.LENGTH_LONG).show();return;}if(!a.replaceAll("[\\s()\\-]","").matches("\\+?[0-9]{5,20}")){Toast.makeText(this,"رقم التوجيه غير صالح",Toast.LENGTH_LONG).show();return;}long id=db.createForwardRule(n,a);if(id<0)Toast.makeText(this,"تعذر حفظ القاعدة؛ قد يكون الاسم مستخدمًا",Toast.LENGTH_LONG).show();else{Toast.makeText(this,"تم حفظ قاعدة التوجيه",Toast.LENGTH_SHORT).show();render();}}).show();}
 void forwardFailedWithRule(String originalAddress,String body){android.database.Cursor c=db.listForwardRules();ArrayList<Long> ids=new ArrayList<>();ArrayList<String> labels=new ArrayList<>();ArrayList<String> destinations=new ArrayList<>();while(c.moveToNext()){ids.add(c.getLong(c.getColumnIndexOrThrow("id")));labels.add(c.getString(c.getColumnIndexOrThrow("name"))+" — "+c.getString(c.getColumnIndexOrThrow("destination")));destinations.add(c.getString(c.getColumnIndexOrThrow("destination")));}c.close();if(ids.isEmpty()){new AlertDialog.Builder(this).setMessage("لا توجد قواعد توجيه. أضف قاعدة أولًا من تبويب قواعد التوجيه.").setPositiveButton("حسنًا",null).show();return;}new AlertDialog.Builder(this).setTitle("اختر قاعدة التوجيه").setItems(labels.toArray(new String[0]),(dialog,which)->new AlertDialog.Builder(this).setTitle("تأكيد التوجيه").setMessage("ستُرسل نسخة من نص الرسالة الفاشلة إلى "+destinations.get(which)+" عبر القاعدة: "+labels.get(which)+". لن تُرسل إلى المستلم الأصلي بهذه الخطوة.").setNegativeButton("إلغاء",null).setPositiveButton("توجيه الآن",(d,w)->send(destinations.get(which),body)).show()).setNegativeButton("إلغاء",null).show();}
