   void loadPeople(){if(checkSelfPermission("android.permission.READ_CONTACTS")==PackageManager.PERMISSION_GRANTED){android.database.Cursor c=null;try{c=getContentResolver().query(ContactsContract.CommonDataKinds.Phone.CONTENT_URI,new String[]{ContactsContract.CommonDataKinds.Phone.DISPLAY_NAME,ContactsContract.CommonDataKinds.Phone.NUMBER},null,null,ContactsContract.CommonDataKinds.Phone.DISPLAY_NAME+" COLLATE NOCASE ASC");if(c!=null)while(c.moveToNext()){String n=c.getString(0),p=c.getString(1);if(p!=null&&!p.trim().isEmpty())people.add(new Person(n==null?"":n,p.trim()));}}catch(Exception e){android.util.Log.e("HashemSMS","Compose contacts query failed",e);}finally{if(c!=null)c.close();}}
    if(people.isEmpty()){android.database.Cursor c=null;try{c=db.listThreads("all");while(c.moveToNext()){String n=c.getString(c.getColumnIndexOrThrow("address"));if(n!=null&&!n.trim().isEmpty())people.add(new Person("",n.trim()));}}catch(Exception ignored){}finally{if(c!=null)c.close();}}
    LinkedHashMap<String,Person> unique=new LinkedHashMap<>();for(Person p:people)unique.putIfAbsent(phoneKey(p.number),p);people.clear();people.addAll(unique.values());}
   String norm(String x){StringBuilder b=new StringBuilder();String s=x==null?"":x.toLowerCase(Locale.ROOT);for(int i=0;i<s.length();i++){char c=s.charAt(i);if(c==0x0640||(c>=0x064B&&c<=0x065F)||c==0x0670)continue;if("أإآٱ".indexOf(c)>=0)c='ا';else if(c=='ة')c='ه';else if(c=='ى')c='ي';else if(c>='٠'&&c<='٩')c=(char)('0'+c-'٠');else if(c>='۰'&&c<='۹')c=(char)('0'+c-'۰');b.append(c);}return b.toString();}
   String dialNumber(String x){String n=norm(x);StringBuilder b=new StringBuilder();for(int i=0;i<n.length();i++){char c=n.charAt(i);if(Character.isDigit(c)||c=='+')b.append(c);}return b.toString();}
   String phoneKey(String x){String n=norm(x);StringBuilder b=new StringBuilder();for(int i=0;i<n.length();i++)if(Character.isDigit(n.charAt(i)))b.append(n.charAt(i));String p=b.toString();while(p.startsWith("0"))p=p.substring(1);if(p.startsWith("967"))p=p.substring(3);while(p.startsWith("0"))p=p.substring(1);return p;}
   ArrayList<String> tokens(){ArrayList<String> t=new ArrayList<>();for(String x:norm(query.getText().toString()).trim().split("\\s+"))if(!x.isEmpty())t.add(x);return t;}
   boolean match(Person p,ArrayList<String> ts){String n=norm(p.name),num=phoneKey(p.number);for(String t:ts)if(!n.contains(t)&&(phoneKey(t).isEmpty()||!num.contains(phoneKey(t))))return false;return true;}
   ArrayList<Person> results(){ArrayList<Person> r=new ArrayList<>();ArrayList<String> ts=tokens();for(Person p:people)if(match(p,ts))r.add(p);return r;}
   boolean phoneQuery(){String q=norm(query.getText().toString()).trim();return q.matches("[+0-9٠-٩۰-۹()\\s.-]+")&&phoneKey(q).length()>=6;}
   void render(){heading.setText(step==1?"مجموعة جديدة":step==2?"تفاصيل المجموعة":step==3?"تم إنشاء المجموعة":step==4?"إرسال رسالة للمجموعة":"محادثة جديدة");groupButton.setVisibility(step==0?View.VISIBLE:View.GONE);query.setVisibility(step==0||step==1?View.VISIBLE:View.GONE);chipScroll.setVisibility(step==0||step==1?View.VISIBLE:View.GONE);allButton.setVisibility(step==0||step==1?View.VISIBLE:View.GONE);summary.setVisibility(step==0||step==1?View.VISIBLE:View.GONE);scroll.setVisibility(step==0||step==1?View.VISIBLE:View.GONE);body.setVisibility(step==0||step==4?View.VISIBLE:View.GONE);action.setText(step==1?"التالي":step==2?"إنشاء المجموعة":"إرسال");bottomBar.setVisibility(step==3?View.GONE:View.VISIBLE);renderChips();if(step==2){details();return;}if(step==3){confirmation();return;}renderRows();}
