    String section="";for(Person p:found){if(step==0&&phoneQuery()&&phoneKey(p.number).equals(phoneKey(query.getText().toString())))continue;String letter=p.name.trim().isEmpty()?"#":p.name.trim().substring(0,1).toUpperCase(Locale.ROOT);if(!letter.equals(section)){section=letter;TextView heading=tv(section,13);heading.setTypeface(androidx.core.content.res.ResourcesCompat.getFont(MainActivity.this,R.font.almarai_bold));heading.setTextColor(UiResources.color(MainActivity.this,R.color.on_surface_variant));heading.setPadding(UiResources.dp(MainActivity.this,14),UiResources.dp(MainActivity.this,8),UiResources.dp(MainActivity.this,14),UiResources.dp(MainActivity.this,4));rows.addView(heading,new LinearLayout.LayoutParams(-1,-2));}visible.add(p);row(p,false);}
