   void act(){if(step==1){if(selected.size()<2){Toast.makeText(MainActivity.this,"اختر عضوين على الأقل",Toast.LENGTH_SHORT).show();return;}step=2;render();return;}if(step==2){String n=groupName.getText().toString().trim();if(n.isEmpty()){Toast.makeText(MainActivity.this,"أدخل اسم المجموعة",Toast.LENGTH_SHORT).show();return;}groupId=db.createGroup(n);if(groupId<0){Toast.makeText(MainActivity.this,"تعذر حفظ المجموعة؛ قد يكون الاسم مستخدمًا",Toast.LENGTH_LONG).show();return;}groupNameSaved=n;for(Person p:selected.values())db.addGroupMember(groupId,p.number,p.name);step=3;render();return;}if(step==3){selected.clear();query.setText("");step=1;render();return;}if(selected.isEmpty()){Toast.makeText(MainActivity.this,"اختر مستلماً أولاً",Toast.LENGTH_SHORT).show();return;}String text=body.getText().toString();if(text.trim().isEmpty()){Toast.makeText(MainActivity.this,"اكتب نص الرسالة أولاً",Toast.LENGTH_SHORT).show();return;}StringBuilder nums=new StringBuilder();for(Person p:selected.values()){if(nums.length()>0)nums.append('\n');nums.append(dialNumber(p.number));}dlg.dismiss();sendToComposeRecipients(nums.toString(),text);}
