void pickContactsForCompose(EditText destination){
  if(checkSelfPermission("android.permission.READ_CONTACTS")!=PackageManager.PERMISSION_GRANTED){Toast.makeText(this,"امنح إذن جهات الاتصال أولًا، أو أدخل الرقم يدويًا.",Toast.LENGTH_LONG).show();return;}
  ArrayList<String[]> people=new ArrayList<>();android.database.Cursor c=null;
  try{c=getContentResolver().query(ContactsContract.CommonDataKinds.Phone.CONTENT_URI,new String[]{ContactsContract.CommonDataKinds.Phone.DISPLAY_NAME,ContactsContract.CommonDataKinds.Phone.NUMBER},null,null,ContactsContract.CommonDataKinds.Phone.DISPLAY_NAME+" COLLATE NOCASE ASC");if(c!=null)while(c.moveToNext()){String n=c.getString(0),num=c.getString(1);if(num!=null&&!num.trim().isEmpty())people.add(new String[]{n==null?"":n,num.trim()});}}
  catch(Exception e){android.util.Log.e("HashemSMS","Unable to load contacts for compose",e);Toast.makeText(this,"تعذّر تحميل جهات الاتصال.",Toast.LENGTH_LONG).show();return;}finally{if(c!=null)try{c.close();}catch(Exception ignored){}}
  if(people.isEmpty()){Toast.makeText(this,"لا توجد أرقام جهات اتصال.",Toast.LENGTH_SHORT).show();return;}
  LinkedHashMap<String,String[]> selected=new LinkedHashMap<>();for(String token:destination.getText().toString().split("[,;\\n]")){String n=token.trim().replaceAll("[\\s()\\-]","");if(!n.isEmpty())selected.put(n,new String[]{"",n});}
  LinearLayout panel=new LinearLayout(this);panel.setOrientation(LinearLayout.VERTICAL);EditText query=new EditText(this);query.setSingleLine(true);query.setHint("ابحث بالاسم أو الرقم");panel.addView(query);TextView count=tv("",14);panel.addView(count);
  LinearLayout actionRow=new LinearLayout(this);Button allButton=button("تحديد النتائج الظاهرة");Button clearButton=button("مسح التحديد");actionRow.addView(allButton,new LinearLayout.LayoutParams(0,-2,1));actionRow.addView(clearButton,new LinearLayout.LayoutParams(0,-2,1));panel.addView(actionRow);
  LinearLayout rows=new LinearLayout(this);rows.setOrientation(LinearLayout.VERTICAL);ScrollView scroll=new ScrollView(this);scroll.addView(rows);panel.addView(scroll,new LinearLayout.LayoutParams(-1,UiResources.dp(this,360)));
  final ArrayList<CheckBox> visibleChecks=new ArrayList<>();final String[] q={""};final boolean[] dragging={false};final boolean[] dragValue={true};
  Runnable refresh=()->{rows.removeAllViews();visibleChecks.clear();q[0]=query.getText().toString().trim().toLowerCase(Locale.ROOT);for(String[] person:people){String name=person[0],number=person[1],key=number.replaceAll("[\\s()\\-]","");if(!q[0].isEmpty()&&!name.toLowerCase(Locale.ROOT).contains(q[0])&&!number.toLowerCase(Locale.ROOT).contains(q[0]))continue;CheckBox cb=new CheckBox(this);cb.setText(name.isEmpty()?number:name+" · "+number);cb.setTextSize(14);cb.setChecked(selected.containsKey(key));cb.setOnCheckedChangeListener((v,checked)->{if(checked)selected.put(key,new String[]{name,key});else selected.remove(key);count.setText(getString(R.string.compose_selected_count,selected.size()));});final float[] downY={0f};cb.setOnTouchListener((v,event)->{if(event.getAction()==android.view.MotionEvent.ACTION_DOWN){dragging[0]=false;dragValue[0]=!cb.isChecked();downY[0]=event.getY();}else if(event.getAction()==android.view.MotionEvent.ACTION_MOVE){if(Math.abs(event.getY()-downY[0])>android.view.ViewConfiguration.get(MainActivity.this).getScaledTouchSlop()){dragging[0]=true;scroll.requestDisallowInterceptTouchEvent(true);}if(dragging[0])cb.setChecked(dragValue[0]);}else if(event.getAction()==android.view.MotionEvent.ACTION_UP||event.getAction()==android.view.MotionEvent.ACTION_CANCEL){dragging[0]=false;scroll.requestDisallowInterceptTouchEvent(false);}return false;});visibleChecks.add(cb);rows.addView(cb);View line=new View(this);line.setBackgroundColor(UiResources.color(MainActivity.this,R.color.divider));rows.addView(line,new LinearLayout.LayoutParams(-1,1));}if(visibleChecks.isEmpty())rows.addView(tv("لا توجد نتائج مطابقة",14));count.setText(getString(R.string.compose_contacts_count,selected.size(),visibleChecks.size()));};
  query.addTextChangedListener(new android.text.TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int c0,int a){}public void onTextChanged(CharSequence s,int st,int before,int count0){refresh.run();}public void afterTextChanged(android.text.Editable e){}});
  allButton.setOnClickListener(v->{for(String[] person:people){String name=person[0],number=person[1];if(!q[0].isEmpty()&&!name.toLowerCase(Locale.ROOT).contains(q[0])&&!number.toLowerCase(Locale.ROOT).contains(q[0]))continue;String key=number.replaceAll("[\\s()\\-]","");selected.put(key,new String[]{name,key});}refresh.run();});
  clearButton.setOnClickListener(v->{selected.clear();refresh.run();});refresh.run();
  AlertDialog dlg=new AlertDialog.Builder(this).setTitle("اختيار المستلمين").setView(panel).setNegativeButton("إلغاء",null).setPositiveButton("إضافة المحددين",null).create();dlg.setOnShowListener(v->dlg.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(btn->{if(selected.isEmpty()){Toast.makeText(this,"حدد مستلمًا واحدًا على الأقل",Toast.LENGTH_SHORT).show();return;}StringBuilder result=new StringBuilder();for(String[] item:selected.values()){if(result.length()>0)result.append("\\n");result.append(item[1]);}destination.setText(result.toString());dlg.dismiss();}));dlg.show();
 }
 void sendToComposeRecipients(String raw,String body){String[] tokens=(raw==null?"":raw.trim()).split("[,;\\n]");LinkedHashMap<String,String[]> unique=new LinkedHashMap<>();for(String token:tokens){String number=token.trim().replaceAll("[\\s()\\-]","");if(number.isEmpty())continue;if(!number.matches("\\+?[0-9]{5,20}")){Toast.makeText(this,"رقم غير صالح: "+token.trim(),Toast.LENGTH_LONG).show();return;}unique.put(number,new String[]{number,""});}if(unique.isEmpty()||body==null||body.trim().isEmpty()){Toast.makeText(this,"أدخل رقمًا واحدًا على الأقل ونص الرسالة",Toast.LENGTH_SHORT).show();return;}if(unique.size()==1){String only=unique.keySet().iterator().next();send(only,body);openContactConversation(only);return;}ArrayList<String[]> recipients=new ArrayList<>(unique.values());final android.content.Context appContext=getApplicationContext();final Db appDb=new Db(appContext);chooseSmsSubscription(new SubscriptionChoiceCallback(){public void onSelected(int subId){SmsSending.enqueueBulkSend(appContext,appDb,recipients,body,subId);}public void onCancelled(){}});}

 void send(String a,String b){
  final String recipient=a==null?"":a.trim(),body=b==null?"":b;if(recipient.isEmpty()||body.trim().isEmpty()){Toast.makeText(this,"أدخل رقم الهاتف ونص الرسالة",Toast.LENGTH_SHORT).show();return;}
  final android.content.Context appContext=getApplicationContext();final Db appDb=new Db(appContext);chooseSmsSubscription(new SubscriptionChoiceCallback(){public void onSelected(int subId){SmsSending.SEND_EXECUTOR.execute(()->SmsSending.sendSmsInBackground(appContext,appDb,recipient,body,"MAIN",1000,2000,subId,true));}public void onCancelled(){}});
 }
 void chooseSmsSubscription(SubscriptionChoiceCallback action){
  try{android.telephony.TelephonyManager tm=(android.telephony.TelephonyManager)getSystemService(TELEPHONY_SERVICE);if(tm==null||tm.getPhoneCount()<=1){action.onSelected(-1);return;}}catch(SecurityException e){action.onCancelled();return;}
  if(checkSelfPermission("android.permission.READ_PHONE_STATE")!=PackageManager.PERMISSION_GRANTED){pendingSubscriptionAction=action;requestPermissions(new String[]{"android.permission.READ_PHONE_STATE"},61);return;}showSmsSubscriptionChoices(action);
 }
 @android.annotation.SuppressLint("MissingPermission") void showSmsSubscriptionChoices(SubscriptionChoiceCallback callback){
  final java.util.concurrent.atomic.AtomicBoolean resolved=new java.util.concurrent.atomic.AtomicBoolean(false);
  SubscriptionChoiceCallback once=new SubscriptionChoiceCallback(){public void onSelected(int id){if(resolved.compareAndSet(false,true))callback.onSelected(id);}public void onCancelled(){if(resolved.compareAndSet(false,true))callback.onCancelled();}};
  try{java.util.List<android.telephony.SubscriptionInfo> infos=android.telephony.SubscriptionManager.from(this).getActiveSubscriptionInfoList();
   if(infos==null||infos.isEmpty()){android.util.Log.w("HashemSMS","No active SIM list; cancelling send rather than silently using default");Toast.makeText(this,"لا توجد شريحة SIM نشطة؛ أُلغي الإرسال.",Toast.LENGTH_SHORT).show();once.onCancelled();return;}
   if(infos.size()==1){once.onSelected(infos.get(0).getSubscriptionId());return;}String[] labels=new String[infos.size()];
   for(int i=0;i<infos.size();i++){android.telephony.SubscriptionInfo info=infos.get(i);String name;try{CharSequence display=info.getDisplayName();name=display==null||display.toString().trim().isEmpty()?"SIM "+(info.getSimSlotIndex()+1):display.toString();}catch(RuntimeException e){name="SIM "+(info.getSimSlotIndex()+1);}
    String number="";try{String value=info.getNumber();if(value!=null)number=value.trim();}catch(RuntimeException e){android.util.Log.w("HashemSMS","Could not read SIM phone number for slot "+(info.getSimSlotIndex()+1),e);}labels[i]=name+(number.isEmpty()?"":" · "+number);}
   new AlertDialog.Builder(this).setTitle("اختر شريحة الإرسال").setItems(labels,(dialog,which)->{if(which>=0&&which<infos.size())once.onSelected(infos.get(which).getSubscriptionId());else once.onCancelled();}).setNegativeButton("إرسال بالشريحة الافتراضية",(dialog,which)->once.onSelected(-1)).setOnCancelListener(dialog->once.onCancelled()).show();
  }catch(SecurityException e){android.util.Log.w("HashemSMS","SIM list permission denied; cancelling send",e);Toast.makeText(this,"تعذّرت قراءة الشرائح؛ أُلغي الإرسال.",Toast.LENGTH_SHORT).show();once.onCancelled();}catch(RuntimeException e){android.util.Log.w("HashemSMS","SIM list could not be fetched; cancelling send",e);Toast.makeText(this,"تعذّر جلب قائمة الشرائح؛ أُلغي الإرسال.",Toast.LENGTH_SHORT).show();once.onCancelled();}
 }
 @Override public void onRequestPermissionsResult(int requestCode,String[] permissions,int[] grantResults){
  super.onRequestPermissionsResult(requestCode,permissions,grantResults);if(requestCode==81){if(grantResults.length>0&&grantResults[0]==PackageManager.PERMISSION_GRANTED){synchronized(contactCache){contactCache.clear();contactCacheGeneration++;}synchronized(contactBitmapCache){contactBitmapCache.evictAll();}contactsLoaded=false;showContactsScreen();}else showContactsPermissionState();requestNotificationPermissionIfNeeded();return;}if(requestCode==5){basePermissionRequestPending=false;if(!requestContactsPermissionAtStartupOnce())requestNotificationPermissionIfNeeded();return;}if(requestCode==70){if(grantResults==null||grantResults.length==0||grantResults[0]!=PackageManager.PERMISSION_GRANTED)Toast.makeText(this,"لن تظهر إشعارات الرسائل دون الإذن.",Toast.LENGTH_SHORT).show();return;}if(requestCode!=61)return;SubscriptionChoiceCallback callback=pendingSubscriptionAction;pendingSubscriptionAction=null;if(callback==null)return;
  if(grantResults!=null&&grantResults.length>0&&grantResults[0]==PackageManager.PERMISSION_GRANTED)showSmsSubscriptionChoices(callback);else{Toast.makeText(this,"لم يُمنح إذن قراءة حالة الهاتف؛ سيتم الإرسال بالشريحة الافتراضية.",Toast.LENGTH_SHORT).show();callback.onSelected(-1);}
 }
 void schedule(String a,String b){Calendar cal=Calendar.getInstance();cal.add(Calendar.MINUTE,5);DatePickerDialog datePicker=new DatePickerDialog(this,(view,year,month,day)->{cal.set(Calendar.YEAR,year);cal.set(Calendar.MONTH,month);cal.set(Calendar.DAY_OF_MONTH,day);TimePickerDialog timePicker=new TimePickerDialog(this,(timeView,hour,minute)->{cal.set(Calendar.HOUR_OF_DAY,hour);cal.set(Calendar.MINUTE,minute);cal.set(Calendar.SECOND,0);cal.set(Calendar.MILLISECOND,0);long when=cal.getTimeInMillis();if(when<=System.currentTimeMillis()){Toast.makeText(this,"اختر موعدًا في المستقبل",Toast.LENGTH_LONG).show();return;}confirmSchedule(a,b,when);},cal.get(Calendar.HOUR_OF_DAY),cal.get(Calendar.MINUTE),true);timePicker.setTitle("اختر وقت الإرسال");timePicker.show();},cal.get(Calendar.YEAR),cal.get(Calendar.MONTH),cal.get(Calendar.DAY_OF_MONTH));datePicker.setTitle("اختر تاريخ الإرسال");datePicker.getDatePicker().setMinDate(System.currentTimeMillis());datePicker.show();}
 void confirmSchedule(String a,String b,long when){
  String whenText=new java.text.SimpleDateFormat("yyyy-MM-dd HH:mm",Locale.getDefault()).format(new Date(when));
  new AlertDialog.Builder(this).setTitle("تأكيد جدولة الرسالة").setMessage("سيتم إرسال الرسالة إلى "+a+" في "+whenText+".").setNegativeButton("إلغاء",null).setPositiveButton("تأكيد الجدولة",(d,w)->{
   long messageId=db.addMessage(a,b,"out","scheduled");if(messageId<=0){Toast.makeText(this,"تعذّر حفظ الرسالة المجدولة",Toast.LENGTH_LONG).show();return;}db.saveSchedule(messageId,a,b,when);
   boolean exact=AlarmScheduler.scheduleBestEffort(this,messageId,a,b,when);
   if(Build.VERSION.SDK_INT>=31&&!exact){AlarmScheduler.rememberPendingExactRequest(this,messageId);
    new AlertDialog.Builder(this).setTitle("إذن المنبّه الدقيق").setMessage("لم يُمنح إذن المنبّه الدقيق. ستعمل الرسالة الآن بموعد تقريبي. يمكنك فتح إعدادات الإذن لتحسين دقة الموعد.")
     .setPositiveButton("فتح إعدادات المنبّه الدقيق",(dialog,which)->{try{startActivity(new Intent(android.provider.Settings.ACTION_REQUEST_SCHEDULE_EXACT_ALARM,android.net.Uri.parse("package:"+getPackageName())));}catch(Exception e){AlarmScheduler.clearPendingExactRequest(this);Toast.makeText(this,"تعذّر فتح إعدادات الإذن؛ ستبقى الجدولة تقريبية",Toast.LENGTH_LONG).show();}})
     .setNegativeButton("استخدام موعد تقريبي",(dialog,which)->{AlarmScheduler.clearPendingExactRequest(this);Toast.makeText(this,"تمت الجدولة بموعد تقريبي",Toast.LENGTH_LONG).show();})
     .setOnCancelListener(dialog->{AlarmScheduler.clearPendingExactRequest(this);Toast.makeText(this,"تمت الجدولة بموعد تقريبي",Toast.LENGTH_LONG).show();}).show();
   }else Toast.makeText(this,"تمت جدولة الرسالة بالمنبّه الدقيق",Toast.LENGTH_LONG).show();render();
  }).show();
 }
 void scheduledScreen(){list.addView(tv("الرسائل المجدولة",22));list.addView(tv("راجع الرسائل التي تنتظر الإرسال أو ألغِ جدولتها قبل موعدها.",14));android.database.Cursor c=db.listSchedules();int n=0;while(c.moveToNext()){long id=c.getLong(c.getColumnIndexOrThrow("id"));String a=c.getString(c.getColumnIndexOrThrow("address"));String body=c.getString(c.getColumnIndexOrThrow("body"));long at=c.getLong(c.getColumnIndexOrThrow("at"));LinearLayout card=new LinearLayout(this);card.setOrientation(LinearLayout.VERTICAL);styleScreenCard(card);card.addView(tv("إلى: "+a,16));card.addView(tv(body,16));card.addView(tv("الموعد: "+new java.text.SimpleDateFormat("yyyy-MM-dd HH:mm",Locale.getDefault()).format(new Date(at)),13));Button cancel=button("إلغاء الجدولة");cancel.setOnClickListener(v->new AlertDialog.Builder(this).setTitle("إلغاء الرسالة المجدولة").setMessage("لن تُرسل هذه الرسالة في الموعد المحدد.").setNegativeButton("العودة",null).setPositiveButton("إلغاء الجدولة",(d,w)->{if(db.cancelSchedule(id)){AlarmScheduler.cancel(this,id,a,body);render();Toast.makeText(this,"تم إلغاء الجدولة",Toast.LENGTH_SHORT).show();}else Toast.makeText(this,"تم تنفيذ الرسالة أو إلغاء جدولتها بالفعل",Toast.LENGTH_LONG).show();}).show());card.addView(cancel);list.addView(card);View line=new View(this);line.setBackgroundColor(UiResources.color(MainActivity.this,R.color.divider));list.addView(line,new LinearLayout.LayoutParams(-1,1));n++;}c.close();if(n==0)list.addView(tv("لا توجد رسائل مجدولة حاليًا.",16));}
 void bulkScreen(){list.addView(tv("الرسائل الجماعية",22));list.addView(tv("اكتب رقمًا في كل سطر، ويمكن إضافة الاسم بعد فاصلة: 777123456, أحمد. استخدم {name} داخل نص الرسالة للتخصيص.",14));Button imp=button("استيراد ملف نصي أو CSV");imp.setOnClickListener(v->importFile());list.addView(imp);Button contacts=button("اختيار من جهات الاتصال · بحث وتحديد الكل");contacts.setOnClickListener(v->pickContactsForBulk());list.addView(contacts);bulkNumbers=new EditText(this);bulkNumbers.setHint("الرقم أو الرقم, الاسم — سطر لكل مستلم");bulkNumbers.setMinLines(5);bulkNumbers.setGravity(Gravity.TOP);list.addView(bulkNumbers);bulkBody=new EditText(this);bulkBody.setHint("نص الرسالة. مثال: مرحبًا {name}");bulkBody.setMinLines(4);bulkBody.setGravity(Gravity.TOP);list.addView(bulkBody);Button send=button("مراجعة ثم إرسال");send.setOnClickListener(v->confirmBulk());list.addView(send);}
 void pickContactsForBulk(){
   ArrayList<String[]> all=new ArrayList<>();
   if(checkSelfPermission("android.permission.READ_CONTACTS")!=PackageManager.PERMISSION_GRANTED){
    android.database.Cursor known=null;
    try{known=db.listThreads("all");while(known.moveToNext()){String number=known.getString(known.getColumnIndexOrThrow("address"));if(number!=null&&!number.trim().isEmpty())all.add(new String[]{"",number.trim()});}}
    catch(Exception e){android.util.Log.w("HashemSMS","Unable to load known conversation numbers for bulk picker",e);}
    finally{if(known!=null)try{known.close();}catch(Exception ignored){}}
    if(all.isEmpty()){Toast.makeText(this,"إذن جهات الاتصال غير ممنوح ولا توجد أرقام محادثات محفوظة. يمكنك إدخال الأرقام يدويًا.",Toast.LENGTH_LONG).show();return;}
    Toast.makeText(this,"إذن جهات الاتصال غير ممنوح؛ يعرض المنتقي أرقام المحادثات المحفوظة فقط.",Toast.LENGTH_LONG).show();
   }else{
    android.database.Cursor c=null;
    try{c=getContentResolver().query(ContactsContract.CommonDataKinds.Phone.CONTENT_URI,new String[]{ContactsContract.CommonDataKinds.Phone.DISPLAY_NAME,ContactsContract.CommonDataKinds.Phone.NUMBER},null,null,ContactsContract.CommonDataKinds.Phone.DISPLAY_NAME+" COLLATE NOCASE ASC");if(c!=null)while(c.moveToNext()){String name=c.getString(0),number=c.getString(1);if(number==null)continue;number=number.trim();if(number.isEmpty())continue;all.add(new String[]{name==null?"":name,number});}}
    catch(Exception e){android.util.Log.e("HashemSMS","Unable to read contacts for bulk picker",e);Toast.makeText(this,"تعذّر قراءة جهات الاتصال. تحقق من الإذن.",Toast.LENGTH_LONG).show();return;}
    finally{if(c!=null)try{c.close();}catch(Exception ignored){}}
   }
   if(all.isEmpty()){Toast.makeText(this,"لا توجد أرقام في جهات الاتصال.",Toast.LENGTH_LONG).show();return;}
   LinkedHashMap<String,String[]> selected=new LinkedHashMap<>();
   LinearLayout panel=new LinearLayout(this);panel.setOrientation(LinearLayout.VERTICAL);panel.setPadding(4,4,4,4);
   EditText query=new EditText(this);query.setSingleLine(true);query.setHint("ابحث باسم أو جزء من الرقم");panel.addView(query,new LinearLayout.LayoutParams(-1,-2));
   TextView count=tv("المحدد: 0",14);panel.addView(count);
   LinearLayout actions=new LinearLayout(this);actions.setOrientation(LinearLayout.HORIZONTAL);
   Button selectAll=button("تحديد كل النتائج");Button clear=button("إلغاء التحديد");
   actions.addView(selectAll,new LinearLayout.LayoutParams(0,-2,1));actions.addView(clear,new LinearLayout.LayoutParams(0,-2,1));panel.addView(actions);
   LinearLayout rows=new LinearLayout(this);rows.setOrientation(LinearLayout.VERTICAL);ScrollView scroll=new ScrollView(this);scroll.setFillViewport(false);scroll.addView(rows);int pickerHeight=(int)(getResources().getDisplayMetrics().density*360);panel.addView(scroll,new LinearLayout.LayoutParams(-1,pickerHeight));
   final String[] currentQuery={""};
   Runnable refresh=()->{
    rows.removeAllViews();currentQuery[0]=query.getText().toString().trim().toLowerCase(Locale.ROOT);int shown=0;
    for(String[] person:all){String name=person[0],number=person[1];if(!currentQuery[0].isEmpty()&&!name.toLowerCase(Locale.ROOT).contains(currentQuery[0])&&!number.toLowerCase(Locale.ROOT).contains(currentQuery[0]))continue;
     String key=number.replaceAll("[\\s()\\-]","");CheckBox cb=new CheckBox(this);cb.setText((name.isEmpty()?number:name+"  ·  "+number));cb.setTextSize(14);cb.setPadding(8,5,8,5);cb.setChecked(selected.containsKey(key));cb.setOnCheckedChangeListener((v,checked)->{if(checked)selected.put(key,new String[]{name,key});else selected.remove(key);count.setText(getString(R.string.compose_selected_count,selected.size()));});rows.addView(cb);View line=new View(this);line.setBackgroundColor(UiResources.color(MainActivity.this,R.color.divider));rows.addView(line,new LinearLayout.LayoutParams(-1,1));shown++;
    }
    if(shown==0)rows.addView(tv("لا توجد نتائج مطابقة",15));count.setText(getString(R.string.compose_contacts_count,selected.size(),shown));
   };
   query.addTextChangedListener(new android.text.TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int c,int a){}public void onTextChanged(CharSequence s,int st,int before,int count){refresh.run();}public void afterTextChanged(android.text.Editable e){}});
   selectAll.setOnClickListener(v->{String q=currentQuery[0];for(String[] person:all){String name=person[0],number=person[1];if(!q.isEmpty()&&!name.toLowerCase(Locale.ROOT).contains(q)&&!number.toLowerCase(Locale.ROOT).contains(q))continue;String key=number.replaceAll("[\\s()\\-]","");selected.put(key,new String[]{name,key});}refresh.run();});
   clear.setOnClickListener(v->{selected.clear();refresh.run();});
   refresh.run();
   AlertDialog dialog=new AlertDialog.Builder(this).setTitle("اختيار المستلمين").setView(panel).setNegativeButton("إلغاء",null).setPositiveButton("إضافة المحددين",null).create();
   dialog.setOnShowListener(v->{dialog.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(btn->{if(selected.isEmpty()){Toast.makeText(this,"حدد مستلمًا واحدًا على الأقل",Toast.LENGTH_SHORT).show();return;}StringBuilder text=new StringBuilder(bulkNumbers==null?"":bulkNumbers.getText().toString().trim());for(String[] person:selected.values()){String number=person[1];if(bulkContainsNumber(text.toString(),number))continue;if(text.length()>0)text.append('\n');text.append(number);if(!person[0].trim().isEmpty())text.append(", ").append(person[0].trim());}if(bulkNumbers!=null)bulkNumbers.setText(text.toString());Toast.makeText(this,"أُضيف "+selected.size()+" جهة محددة إلى القائمة؛ راجع التكرار قبل الإرسال.",Toast.LENGTH_LONG).show();dialog.dismiss();});});
   dialog.show();
  }
  boolean bulkContainsNumber(String current,String number){String target=number.replaceAll("[\\s()\\-]","");for(String line:current.split("\\r?\\n")){String first=line.trim().split(",",2)[0].replaceAll("[\\s()\\-]","");if(first.equals(target))return true;}return false;}
 void confirmBulk(){
  String raw=bulkNumbers.getText().toString().trim(),body=bulkBody.getText().toString().trim();if(raw.isEmpty()||body.isEmpty()){Toast.makeText(this,"أدخل المستلمين ونص الرسالة أولًا",Toast.LENGTH_SHORT).show();return;}
  ArrayList<String[]> recipients=new ArrayList<>();HashSet<String> seenNumbers=new HashSet<>();int invalid=0;boolean firstLine=true;
  for(String line:raw.split("\\r?\\n")){String[] p=line.trim().split(",",2);String number=p[0].trim();if(firstLine&&(number.toLowerCase(Locale.ROOT).contains("phone")||number.toLowerCase(Locale.ROOT).contains("number")||number.contains("رقم"))){firstLine=false;continue;}firstLine=false;if(number.isEmpty())continue;number=number.replaceAll("[\\s()\\-]","");if(!number.matches("\\+?[0-9]{5,20}")){invalid++;continue;}String name=p.length>1?p[1].trim():"";if(seenNumbers.add(number))recipients.add(new String[]{number,name});}
  if(recipients.isEmpty()){Toast.makeText(this,"لم يتم العثور على أرقام صالحة؛ استخدم رقمًا واحدًا في كل سطر.",Toast.LENGTH_LONG).show();return;}
  final int invalidCount=invalid;new AlertDialog.Builder(this).setTitle("تأكيد الرسائل الجماعية").setMessage("سيتم إرسال "+recipients.size()+" رسالة نصية"+(invalidCount>0?"، وسيتم تجاهل "+invalidCount+" سطر غير صالح":"")+". قد تُحتسب رسوم من شركة الاتصالات. أرسل فقط لمن وافقوا على تلقي الرسائل.")
  .setNegativeButton("مراجعة",null).setPositiveButton("إرسال",(dialog,which)->chooseSmsSubscription(new SubscriptionChoiceCallback(){public void onSelected(int subId){Toast.makeText(MainActivity.this,"بدأت معالجة قائمة الإرسال في الخلفية؛ ستُحدَّث حالة كل مستلم على حدة.",Toast.LENGTH_LONG).show();android.content.Context appContext=getApplicationContext();Db appDb=new Db(appContext);SmsSending.enqueueBulkSend(appContext,appDb,recipients,body,subId);}public void onCancelled(){}})).show();
 }
 void groupsScreen(){list.addView(tv("مجموعات المستلمين",22));list.addView(tv("احفظ أسماء المجموعات وأرقام أعضائها، ثم حمّل المجموعة إلى شاشة الرسائل الجماعية.",14));Button add=button("إنشاء مجموعة");add.setCompoundDrawablesRelativeWithIntrinsicBounds(R.drawable.ic_add,0,0,0);add.setCompoundDrawablePadding(UiResources.dp(MainActivity.this,6));add.setOnClickListener(v->createGroupDialog());list.addView(add);android.database.Cursor c=db.listGroups();int n=0;while(c.moveToNext()){long gid=c.getLong(c.getColumnIndexOrThrow("id"));String name=c.getString(c.getColumnIndexOrThrow("name"));android.database.Cursor members=db.groupMembers(gid);int count=members.getCount();members.close();LinearLayout card=new LinearLayout(this);card.setOrientation(LinearLayout.VERTICAL);styleScreenCard(card);card.addView(tv(name,18));card.addView(tv(count+" مستلم",13));Button use=button("استخدام في الرسائل الجماعية");use.setOnClickListener(v->{android.database.Cursor m=db.groupMembers(gid);StringBuilder numbers=new StringBuilder();while(m.moveToNext()){if(numbers.length()>0)numbers.append('\n');numbers.append(m.getString(m.getColumnIndexOrThrow("address")));String person=m.getString(m.getColumnIndexOrThrow("name"));if(person!=null&&!person.trim().isEmpty())numbers.append(", ").append(person);}m.close();filter="bulk";render();bulkNumbers.setText(numbers.toString());});card.addView(use);Button addMembers=button("إضافة مستلمين");addMembers.setOnClickListener(v->addGroupMembersDialog(gid));card.addView(addMembers);Button delete=button("حذف المجموعة");delete.setOnClickListener(v->new AlertDialog.Builder(this).setTitle("حذف المجموعة").setMessage("سيتم حذف المجموعة وأعضائها المحفوظين، ولن تُحذف الرسائل السابقة.").setNegativeButton("إلغاء",null).setPositiveButton("حذف",(dlg,which)->{db.deleteGroup(gid);render();}).show());card.addView(delete);list.addView(card);View line=new View(this);line.setBackgroundColor(UiResources.color(MainActivity.this,R.color.divider));list.addView(line,new LinearLayout.LayoutParams(-1,1));n++;}c.close();if(n==0)list.addView(tv("لم تنشئ أي مجموعة بعد.",16));}
 void createGroupDialog(){LinearLayout p=new LinearLayout(this);p.setOrientation(LinearLayout.VERTICAL);EditText name=new EditText(this);name.setHint("اسم المجموعة، مثل العائلة أو العمل");EditText members=new EditText(this);members.setHint("رقم الهاتف, الاسم — مستلم في كل سطر");members.setMinLines(5);members.setGravity(Gravity.TOP);p.addView(name);p.addView(members);new AlertDialog.Builder(this).setTitle("إنشاء مجموعة").setView(p).setNegativeButton("إلغاء",null).setPositiveButton("حفظ", (d,w)->{String groupName=name.getText().toString().trim(),raw=members.getText().toString().trim();if(groupName.isEmpty()||raw.isEmpty()){Toast.makeText(this,"أدخل اسم المجموعة ومستلمًا واحدًا على الأقل",Toast.LENGTH_LONG).show();return;}long gid=db.createGroup(groupName);if(gid<0){Toast.makeText(this,"تعذر حفظ المجموعة؛ قد يكون الاسم مستخدمًا من قبل",Toast.LENGTH_LONG).show();return;}int added=0;for(String line:raw.split("\\r?\\n")){String[] part=line.trim().split(",",2);String number=part[0].trim();if(number.isEmpty())continue;db.addGroupMember(gid,number,part.length>1?part[1]:"");added++;}Toast.makeText(this,"تم حفظ المجموعة: "+added+" مستلم",Toast.LENGTH_LONG).show();render();}).show();}
 void addGroupMembersDialog(long gid){LinearLayout p=new LinearLayout(this);p.setOrientation(LinearLayout.VERTICAL);EditText members=new EditText(this);members.setHint("رقم الهاتف, الاسم — مستلم في كل سطر");members.setMinLines(5);members.setGravity(Gravity.TOP);p.addView(members);new AlertDialog.Builder(this).setTitle("إضافة مستلمين للمجموعة").setView(p).setNegativeButton("إلغاء",null).setPositiveButton("حفظ",(dlg,which)->{int added=0,invalid=0;for(String line:members.getText().toString().split("\\r?\\n")){String[] part=line.trim().split(",",2);String number=part[0].trim().replaceAll("[\\s()\\-]","");if(number.isEmpty())continue;if(!number.matches("\\+?[0-9]{5,20}")){invalid++;continue;}db.addGroupMember(gid,number,part.length>1?part[1]:"");added++;}String message="تم حفظ "+added+" مستلم";if(invalid>0)message+="؛ تم تجاهل "+invalid+" رقم غير صالح";Toast.makeText(this,message,Toast.LENGTH_LONG).show();render();}).show();}void importFile(){Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.setType("*/*");i.addCategory(Intent.CATEGORY_OPENABLE);startActivityForResult(i,44);}
 protected void onActivityResult(int r,int c,Intent d){super.onActivityResult(r,c,d);if(r==44&&c==RESULT_OK&&d!=null){try{InputStream in=getContentResolver().openInputStream(d.getData());BufferedReader br=new BufferedReader(new InputStreamReader(in));StringBuilder s=new StringBuilder();String line;while((line=br.readLine())!=null)s.append(line).append('\n');br.close();if(bulkNumbers!=null)bulkNumbers.setText(s.toString());Toast.makeText(this,"تم تحميل محتوى الملف إلى قائمة المستلمين؛ راجعه قبل الإرسال.",Toast.LENGTH_LONG).show();}catch(Exception e){Toast.makeText(this,"تعذّر قراءة الملف: "+e.getMessage(),Toast.LENGTH_LONG).show();}}}

 LinearLayout createContactAvatar(String number,String name){int size=(int)(getResources().getDisplayMetrics().density*52);LinearLayout holder=new LinearLayout(this);holder.setGravity(Gravity.CENTER);FrameLayout avatar=new FrameLayout(this);avatar.setBackground(rounded(UiResources.color(MainActivity.this,R.color.avatar_container),0,size/2));avatar.setClipToOutline(true);ImageView image=new ImageView(this);image.setScaleType(ImageView.ScaleType.CENTER_CROP);image.setTag(number);TextView fallback=new TextView(this);fallback.setGravity(Gravity.CENTER);String label=name==null||name.trim().isEmpty()?number:name.trim();fallback.setText(label.isEmpty()?"?":label.substring(0,1));fallback.setTextSize(18);fallback.setTypeface(Typeface.DEFAULT,Typeface.BOLD);fallback.setTextColor(UiResources.color(MainActivity.this,R.color.primary_variant));fallback.setMaxLines(1);fallback.setEllipsize(android.text.TextUtils.TruncateAt.END);avatar.addView(image,new FrameLayout.LayoutParams(-1,-1));avatar.addView(fallback,new FrameLayout.LayoutParams(-1,-1));android.graphics.Bitmap cached=contactBitmapCache.get(number);if(cached!=null){image.setImageBitmap(cached);image.setVisibility(View.VISIBLE);fallback.setVisibility(View.GONE);}else{image.setVisibility(View.GONE);ContactData data;synchronized(contactCache){data=contactCache.get(number);}if(data!=null&&data.photoUri!=null)loadContactPhotoAsync(number,data.photoUri,image,fallback);}holder.addView(avatar,new LinearLayout.LayoutParams(size,size));return holder;}

 String contactName(String number){synchronized(contactCache){ContactData cached=contactCache.get(number);if(cached!=null)return cached.name;}synchronized(contactLookupPending){if(contactLookupPending.add(number)){DATA_EXECUTOR.execute(()->{loadContactData(number);synchronized(contactLookupPending){contactLookupPending.remove(number);}if(!isFinishing()&&!isDestroyed()){contactRefreshHandler.removeCallbacks(contactRefreshRunnable);contactRefreshHandler.postDelayed(contactRefreshRunnable,500);}});}}return "";}

 boolean requestContactsPermissionAtStartupOnce(){if(checkSelfPermission("android.permission.READ_CONTACTS")==PackageManager.PERMISSION_GRANTED)return false;android.content.SharedPreferences prefs=getSharedPreferences("runtime_permissions",MODE_PRIVATE);if(prefs.getBoolean("contacts_auto_request_done",false))return false;if(prefs.getBoolean("contacts_permission_explained",false)){prefs.edit().putBoolean("contacts_auto_request_done",true).apply();return false;}prefs.edit().putBoolean("contacts_auto_request_done",true).putBoolean("contacts_permission_explained",true).apply();new AlertDialog.Builder(this).setTitle("السماح بجهات الاتصال").setMessage("يُستخدم هذا الإذن لعرض أسماء جهات الاتصال وصورها في القوائم ومنتقي الإرسال. عند رفضه ستظل الأرقام ظاهرة، ويمكنك منح الإذن لاحقًا من تبويب جهات الاتصال.").setNegativeButton("ليس الآن",(d,w)->requestNotificationPermissionIfNeeded()).setPositiveButton("متابعة",(d,w)->requestContactsPermission()).show();return true;}
 void requestPermissionsIfNeeded(){ArrayList<String> needed=new ArrayList<>();String[] base={"android.permission.SEND_SMS","android.permission.RECEIVE_SMS","android.permission.READ_SMS"};for(String p:base)if(checkSelfPermission(p)!=PackageManager.PERMISSION_GRANTED)needed.add(p);if(!needed.isEmpty()){basePermissionRequestPending=true;requestPermissions(needed.toArray(new String[0]),5);return;}if(!requestContactsPermissionAtStartupOnce())requestNotificationPermissionIfNeeded();}
 void requestNotificationPermissionIfNeeded(){if(basePermissionRequestPending||Build.VERSION.SDK_INT<33||!getPackageName().equals(Telephony.Sms.getDefaultSmsPackage(this)))return;String permission="android.permission.POST_NOTIFICATIONS";if(checkSelfPermission(permission)==PackageManager.PERMISSION_GRANTED){getSharedPreferences("runtime_permissions",MODE_PRIVATE).edit().putBoolean("post_notifications_requested",true).apply();return;}android.content.SharedPreferences prefs=getSharedPreferences("runtime_permissions",MODE_PRIVATE);if(prefs.getBoolean("post_notifications_requested",false))return;prefs.edit().putBoolean("post_notifications_requested",true).apply();requestPermissions(new String[]{permission},70);}
 void requestDefault(){if(Build.VERSION.SDK_INT>=29){RoleManager rm=(RoleManager)getSystemService(ROLE_SERVICE);if(rm!=null&&rm.isRoleAvailable(RoleManager.ROLE_SMS)&&!rm.isRoleHeld(RoleManager.ROLE_SMS))startActivityForResult(rm.createRequestRoleIntent(RoleManager.ROLE_SMS),99);}else{Intent i=new Intent(Telephony.Sms.Intents.ACTION_CHANGE_DEFAULT);i.putExtra(Telephony.Sms.Intents.EXTRA_PACKAGE_NAME,getPackageName());startActivity(i);}}
 static class CursorWrapper{android.database.Cursor c;CursorWrapper(android.database.Cursor x){c=x;}boolean moveToNext(){return c.moveToNext();}String getString(String col){return c.getString(c.getColumnIndexOrThrow(col));}void close(){c.close();}}

